describe("partial date ranges are rejected, never silently substituted", () => {
  // Falling back to last_30d when only one bound is given returns a month of
  // data to a caller who asked for a specific window — a wrong answer delivered
  // confidently, with nothing to notice.
  it("rejects `since` without `until`", async () => {
    const fetchImpl = vi.fn().mockResolvedValue(page([]))
    await expect(
      createMetaClient({ accessToken: "t", fetchImpl }).insights.forCampaign("c1", {
        since: "2026-01-01",
      }),
    ).rejects.toThrow(/both `since` and `until`/i)
    expect(fetchImpl).not.toHaveBeenCalled()
  })

  it("rejects `until` without `since`", async () => {
    const fetchImpl = vi.fn().mockResolvedValue(page([]))
    await expect(
      createMetaClient({ accessToken: "t", fetchImpl }).insights.forCampaign("c1", {
        until: "2026-01-31",
      }),
    ).rejects.toThrow(/both `since` and `until`/i)
  })

  it("still accepts a complete range", async () => {
    const fetchImpl = vi.fn().mockResolvedValue(page([]))
    await createMetaClient({ accessToken: "t", fetchImpl }).insights.forCampaign("c1", {
      since: "2026-01-01",
      until: "2026-01-31",
    })
    const q = new URL(fetchImpl.mock.calls[0]![0] as string).searchParams
    expect(q.get("time_range")).toBe('{"since":"2026-01-01","until":"2026-01-31"}')
    expect(q.get("date_preset")).toBeNull()
  })

  it("still accepts a preset when no range is given", async () => {
    const fetchImpl = vi.fn().mockResolvedValue(page([]))
    await createMetaClient({ accessToken: "t", fetchImpl }).insights.forCampaign("c1")
    expect(new URL(fetchImpl.mock.calls[0]![0] as string).searchParams.get("date_preset")).toBe(
      "last_30d",
    )
  })
})

