describe("pagination does not over-fetch", () => {
  it("caps the requested page size to maxItems", async () => {
    const fetchImpl = vi.fn().mockResolvedValue(page([{ id: "a" }]))
    await createTransport({ accessToken: "t", fetchImpl }).getPage("/x", { maxItems: 2 })

    expect(new URL(fetchImpl.mock.calls[0]![0] as string).searchParams.get("limit")).toBe("2")
  })

  it("does not fetch another page once maxItems is already satisfied", async () => {
    const fetchImpl = vi
      .fn()
      .mockImplementation(() => page([{ id: "a" }, { id: "b" }], "https://g/n"))
    const { items, truncated } = await createTransport({ accessToken: "t", fetchImpl }).getPage(
      "/x",
      { maxItems: 2 },
    )

    expect(items).toHaveLength(2)
    expect(truncated).toBe(true)
    expect(fetchImpl).toHaveBeenCalledTimes(1)
  })

  it("never requests a page size above the Graph maximum", async () => {
    const fetchImpl = vi.fn().mockResolvedValue(page([]))
    await createTransport({ accessToken: "t", fetchImpl }).getPage("/x", { maxItems: 100_000 })

    const limit = Number(new URL(fetchImpl.mock.calls[0]![0] as string).searchParams.get("limit"))
    expect(limit).toBeLessThanOrEqual(500)
  })
})
